    var ok = true;
    try {
        cli_execute_command({ command: cmd });
        console.log('  ✅ Local run complete for ' + ticketKey);
    } catch (e) {
        ok = false;
        console.error('  ❌ Local teammate run failed for ' + ticketKey + ': ' + (e.message || e));
    }

