                         res.data.repository.pullRequest.reviewThreads.nodes) || [];
            var resolved = 0;
            nodes.forEach(function (t) { if (t && t.isResolved) resolved++; });
            return { total: nodes.length, resolved: resolved,
                     unresolved: nodes.length - resolved };
        },

